CREATE OR REPLACE FUNCTION public.request_rental_additional_payout(_credit uuid,_amount integer,_reason text,_recipient text,_iban text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Zusatzüberweisungen sind eingestellt. Kaution und Mietguthaben werden über die ursprüngliche Zahlung abgerechnet.' USING ERRCODE='42501'; END $$;
CREATE OR REPLACE FUNCTION public.decide_rental_additional_payout(_id uuid,_approve boolean,_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Zusatzüberweisungen sind eingestellt.' USING ERRCODE='42501'; END $$;
CREATE OR REPLACE FUNCTION public.complete_rental_additional_payout(_id uuid,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Zusatzüberweisungen sind eingestellt.' USING ERRCODE='42501'; END $$;
REVOKE EXECUTE ON FUNCTION public.request_rental_additional_payout(uuid,integer,text,text,text), public.decide_rental_additional_payout(uuid,boolean,text), public.complete_rental_additional_payout(uuid,text) FROM PUBLIC, anon, authenticated;
COMMENT ON TABLE public.rental_additional_payouts IS 'DEPRECATED: compensation transfers retired; retained read-only for historical evidence. Deposit and rental credits must share the original-payment refund cap.';
COMMENT ON TABLE public.rental_additional_payout_events IS 'DEPRECATED: retained append-only evidence for retired compensation transfers.';